WITH filtered AS (SELECT *, CAST(balance AS INT) AS balance_int FROM accounts WHERE customer_id IS NOT NULL AND status IS NOT DISTINCT FROM 'FROZEN') SELECT id, customer_id, balance, opened_date, status, balance_int, LAG(balance, 1) OVER (PARTITION BY status ORDER BY balance, id) AS prev_balance, ROW_NUMBER() OVER (ORDER BY opened_date DESC, id) AS seq_no, LAG(balance_int, 1, 0) OVER (ORDER BY opened_date, id) AS prev_balance_int FROM filtered
